    // Create the sequence counter - 0 to 32
    logic [SEQUENCE_WIDTH-1:0] gearbox_seq;
    logic half_slip;

    always_ff @(posedge i_clk)
    if (i_reset) begin
        gearbox_seq <= '0;
        half_slip <= '0;
    end else begin
        if (!i_slip) begin
            gearbox_seq <= gearbox_seq < 32 ? gearbox_seq + 1 : '0;
