	reg  [3:0] bit_cnt;
	wire       bit_last;

	reg  [8:0] data_reg;

	reg [TW:0] to_cnt;
	wire       to_now;
	reg        to_latch;

	reg        scl_ir;


	// State Machine
	// -------------

	always @(posedge clk)
		if (rst)
			state <= ST_IDLE;
		else
			state <= state_nxt;

	always @(*)
